```python
from html.parser import HTMLParser


def extract_article_info(html):
    class Parser(HTMLParser):
        def __init__(self):
            super().__init__(convert_charrefs=True)  # decode entities for us
            self.articles = []      # one record per container div, in document order
            self.div_stack = []    # track open divs; records for containers, None otherwise
            self.capture = None    # (tag, kind, record) while inside a captured element
            self.buf = []          # accumulated text of the captured element

        def _current_container(self):
            # nearest enclosing container div (handles nested containers)
            for rec in reversed(self.div_stack):
                if rec is not None:
                    return rec
            return None

        def handle_starttag(self, tag, attrs):
            classes = (dict(attrs).get('class') or '').split()
            if tag == 'div':
                if 'container' in classes:
                    rec = {'title': None, 'date': None, 'author': None}
                    self.articles.append(rec)
                    self.div_stack.append(rec)
                else:
                    self.div_stack.append(None)
                return

            rec = self._current_container()
            if rec is None or self.capture is not None:
                return

            kind = None
            if tag == 'h1' and rec['title'] is None:
                kind = 'title'
            elif tag == 'span' and 'date' in classes and rec['date'] is None:
                kind = 'date'
            elif tag == 'span' and 'author' in classes and rec['author'] is None:
                kind = 'author'

            if kind:
                self.capture = (tag, kind, rec)
                self.buf = []

        def handle_endtag(self, tag):
            if tag == 'div':
                if self.div_stack:
                    self.div_stack.pop()
                return
            if self.capture and self.capture[0] == tag:
                _, kind, rec = self.capture
                rec[kind] = ''.join(self.buf).strip()
                self.capture = None
                self.buf = []

        def handle_data(self, data):
            if self.capture:
                self.buf.append(data)

    p = Parser()
    p.feed(html)
    p.close()

    return [
        (a['title'] or 'No Title',
         a['date'] or 'No Date',
         a['author'] or 'No Author')
        for a in p.articles
    ]
```

**How it works:**

- A stack tracks open `<div>` elements so we know which container (if any) we're inside, and to correctly handle nested divs.
- A record is created (in document order) for every `div` whose class list contains `"container"`, so other classes like `class="container article"` still match.
- When inside a container, the *first* `<h1>`, `<span class="date">`, or `<span class="author">` that hasn't been filled yet starts a "capture". Only `handle_data` text is collected, so nested tags are automatically dropped, and `convert_charrefs=True` decodes entities (`&amp;` → `&`, etc.). Only the *first* occurrence counts because the record's field is never `None` afterwards.
- Text is `.strip()`ed, and missing/empty fields fall back to `'No Title'` / `'No Date'` / `'No Author'`.

**Example:**

```python
print(extract_article_info(
    '<div class="container"><h1>Hello</h1><span class="author">Ann</span></div>'
))
# [('Hello', 'No Date', 'Ann')]

print(extract_article_info(
    '<div class="article container"><h1>Hot <em>News</em> &amp; More</h1>'
    '<span class="date  published">2024-01-01</span>'
    '<span class="author">  Bob  </span></div>'
    '<div>No article here</div>'
    '<div class="container"><span class="author">Cara</span><span class="author">Dan</span></div>'
))
# [('Hot News & More', '2024-01-01', 'Bob'), ('No Title', 'No Date', 'Cara')]
```

