import csv
import io


def _maybe_number(value):
    """Convert a string to int or float if possible, else return it unchanged."""
    try:
        return int(value)
    except ValueError:
        try:
            return float(value)
        except ValueError:
            return value


def sort_csv_rows(csv_text, sort_by_column='title'):
    reader = csv.DictReader(io.StringIO(csv_text))
    rows = list(reader)

    if not rows:
        return []

    # Determine which columns are entirely numeric
    numeric_columns = set()
    for column in reader.fieldnames:
        all_numeric = True
        for row in rows:
            value = row[column]
            try:
                float(value)
            except (ValueError, TypeError):
                all_numeric = False
                break
        if all_numeric:
            numeric_columns.add(column)

    # Convert numeric columns to numbers (int when possible, else float)
    for row in rows:
        for column in numeric_columns:
            value = row[column]
            try:
                row[column] = int(value)
            except ValueError:
                row[column] = float(value)

    return sorted(rows, key=lambda row: row[sort_by_column])
```

Example usage:

```python
