import math


def _fill_missing(values):
    """Replace None values with the mean of the present values."""
    present = [v for v in values if v is not None]
    mean = sum(present) / len(present) if present else 0.0
    return [mean if v is None else v for v in values], mean


def _quantile(sorted_data, q):
    """Linear-interpolated quantile of an already-sorted list."""
    n = len(sorted_data)
    if n == 0:
        return 0.0
    if n == 1:
        return float(sorted_data[0])
    pos = (n - 1) * q
    lo = math.floor(pos)
    hi = math.ceil(pos)
    if lo == hi:
        return float(sorted_data[int(pos)])
    frac = pos - lo
    return sorted_data[lo] + frac * (sorted_data[hi] - sorted_data[lo])


def _describe(filled, mean):
    n = len(filled)
    count = float(n)
    if n == 0:
        return {'count': 0.0, 'mean': 0.0, 'std': 0.0, 'min': 0.0,
                '25%': 0.0, '50%': 0.0, '75%': 0.0, 'max': 0.0}
    if n < 2:
        v = float(filled[0])
        return {'count': count, 'mean': mean, 'std': 0.0, 'min': v,
                '25%': v, '50%': v, '75%': v, 'max': v}

    s = sorted(filled)
    variance = sum((x - mean) ** 2 for x in filled) / (n - 1)
    return {
        'count': count,
        'mean': float(mean),
        'std': math.sqrt(variance),
        'min': float(s[0]),
        '25%': _quantile(s, 0.25),
        '50%': _quantile(s, 0.50),
        '75%': _quantile(s, 0.75),
        'max': float(s[-1]),
    }


def describe_filled_columns(columns):
    result = {}
    for name, values in columns.items():
        filled, mean = _fill_missing(values)
        result[name] = _describe(filled, mean)
    return result
```

