def scale_by_group_with_histogram(ids, ages, incomes):
    if len(ids) == 0:
        raise ValueError("no rows")

    n = len(ids)
    # Group row indices by id, preserving first-seen order
    groups = {}
    for i, g in enumerate(ids):
        groups.setdefault(g, []).append(i)

    scaled = [None] * n

    for idxs in groups.values():
        group_ages = [ages[i] for i in idxs]
        group_incomes = [incomes[i] for i in idxs]

        a_min, a_max = min(group_ages), max(group_ages)
        i_min, i_max = min(group_incomes), max(group_incomes)

        for i in idxs:
            if a_max == a_min:
                sa = 0.0
            else:
                sa = (ages[i] - a_min) / (a_max - a_min)
            if i_max == i_min:
                si = 0.0
            else:
                si = (incomes[i] - i_min) / (i_max - i_min)
            scaled[i] = [sa, si]

    # Histogram of scaled incomes into 10 equal-width bins over [0, 1];
    # the last bin includes 1.
    counts = [0] * 10
    for _, si in scaled:
        b = int(si * 10)
        if b > 9:
            b = 9
        if b < 0:
            b = 0
        counts[b] += 1

    return (scaled, counts)
```

