import math
import re

def tfidf_without_urls(texts):
    # Pattern for URLs: http:// or https:// followed by non-whitespace
    url_pattern = re.compile(r'https?://\S+')
    word_pattern = re.compile(r'\w{2,}')

    # Tokenize each document (lowercased words of 2+ chars, URLs removed)
    docs_tokens = [
        word_pattern.findall(url_pattern.sub(' ', text).lower())
        for text in texts
    ]

    n = len(docs_tokens)

    # Document frequencies
    df = {}
    for tokens in docs_tokens:
        for word in set(tokens):
            df[word] = df.get(word, 0) + 1

    if not df:  # every document is empty
        return ([], [])

    vocab = sorted(df)
    vocab_index = {word: i for i, word in enumerate(vocab)}

    # Smoothed IDF
    idf = {word: math.log((1 + n) / (1 + df[word])) + 1 for word in vocab}

    rows = []
    for tokens in docs_tokens:
        # Term counts
        counts = {}
        for word in tokens:
            counts[word] = counts.get(word, 0) + 1

        # Raw TF-IDF vector
        vec = [0.0] * len(vocab)
        for word, count in counts.items():
            vec[vocab_index[word]] = count * idf[word]

        # L2 normalisation
        norm = math.sqrt(sum(x * x for x in vec))
        if norm > 0:
            vec = [x / norm for x in vec]
        rows.append(vec)

    return (rows, vocab)
```

