import re
import math
from collections import Counter, defaultdict


def tfidf_scores_for_question_articles(titles, contents):
    # Pick articles whose title contains "how" or "what" (case-insensitive substring)
    picked_contents = [
        content.lower()
        for title, content in zip(titles, contents)
        if re.search(r'how|what', title.lower())
    ]

    if not picked_contents:
        return {}

    # Tokenize: lowercased runs of two or more word characters
    docs = [re.findall(r'\w{2,}', content) for content in picked_contents]

    n_docs = len(docs)

    # Document frequencies
    df = Counter()
    for doc in docs:
        df.update(set(doc))

    # Smoothed idf
    idf = {word: math.log((1 + n_docs) / (1 + count)) + 1
           for word, count in df.items()}

    # TF-IDF with per-article L2 normalisation, summed across articles
    scores = defaultdict(float)
    for doc in docs:
        tf = Counter(doc)
        vector = {word: tf[word] * idf[word] for word in tf}
        norm = math.sqrt(sum(value * value for value in vector.values()))
        for word, value in vector.items():
            scores[word] += value / norm

    return dict(scores)
```

**How it works on the example:**

1. Only `'How to make pancakes'` is picked (contains "how").
2. Its body tokens: `['make', 'pancakes', 'make', 'friends']` → counts: `make: 2, pancakes: 1, friends: 1`.
3. With one document (`N=1`) and each word in it (`df=1`), `idf = ln(2/2) + 1 = 1` for every word.
4. Raw vector `(2, 1, 1)` is L2-normalised by `√6`, giving `make ≈ 0.8165`, `pancakes ≈ 0.4082`, `friends ≈ 0.4082`, which are then summed (single document, so they pass through unchanged).

