import math
import re


def bracket_free_tfidf(texts):
    # --- Remove text enclosed in square brackets (handles nesting by repeating) ---
    bracket_re = re.compile(r'\[[^\[\]]*\]')
    cleaned = []
    for text in texts:
        while True:
            new_text = bracket_re.sub('', text)
            if new_text == text:
                break
            text = new_text
        cleaned.append(text)

    # --- Tokenize: lowercased runs of 2+ letters/digits/underscores ---
    word_re = re.compile(r'[a-z0-9_]{2,}')
    docs = [word_re.findall(text.lower()) for text in cleaned]

    n = len(texts)

    # --- Document frequency for each word ---
    df = {}
    for doc in docs:
        for word in set(doc):
            df[word] = df.get(word, 0) + 1

    # --- Smoothed idf ---
    idf = {word: math.log((1 + n) / (1 + d)) + 1.0 for word, d in df.items()}

    # --- TF-IDF with raw term counts, normalised to unit Euclidean length ---
    result = []
    for doc in docs:
        counts = {}
        for word in doc:
            counts[word] = counts.get(word, 0) + 1

        scores = {word: count * idf[word] for word, count in counts.items()}

        norm = math.sqrt(sum(s * s for s in scores.values()))
        if norm > 0:
            scores = {word: s / norm for word, s in scores.items()}
        else:
            scores = {}

        result.append(scores)

    return result
