def html_table_records(html, table_id):
    """Extract data records from an HTML table with the given id.

    The table's first row is treated as the header row; every following
    <tr> becomes a dict mapping header text -> cell text (tags removed,
    entities decoded, whitespace stripped). Returns [] if the table has
    no rows, and raises ValueError if no table has that id.
