    class TableParser(HTMLParser):
        def __init__(self, wanted_id):
            super().__init__(convert_charrefs=True)  # entities decoded in data & attrs
            self.wanted_id = wanted_id
            self.found = False        # a table with the id was seen
            self.in_target = False    # currently inside the target table
            self.nested = 0           # depth of tables nested inside the target
            self.rows = []            # completed rows (lists of cell strings)
            self._row = None          # row being built
            self._cell = None         # cell tag name being built
            self._buf = []            # text fragments of the current cell

        def _flush_cell(self):
            if self._cell is not None:
                self._row.append(''.join(self._buf).strip())
                self._cell = None
                self._buf = []

        def _flush_row(self):
            if self._row is not None:
                self._flush_cell()
                self.rows.append(self._row)
                self._row = None

        def handle_starttag(self, tag, attrs):
            if tag == 'table':
                if self.in_target:
                    self.nested += 1          # ignore rows of nested tables
                elif not self.found and dict(attrs).get('id') == self.wanted_id:
                    self.in_target = True
                    self.found = True
                return
            if self.in_target and self.nested == 0:
                if tag == 'tr':
                    self._flush_row()        # tolerate missing </tr>
                    self._row = []
                elif tag in ('td', 'th'):
                    self._flush_cell()       # tolerate missing </td>
                    self._cell = tag
                    self._buf = []

        def handle_endtag(self, tag):
            if tag == 'table':
                if self.in_target:
                    if self.nested:
                        self.nested -= 1
                    else:
                        self._flush_row()
                        self.in_target = False
                return
            if self.in_target and self.nested == 0:
                if tag in ('td', 'th'):
                    self._flush_cell()
                elif tag == 'tr':
                    self._flush_row()

        def handle_data(self, data):
            if self.in_target and self._cell is not None and self.nested == 0:
                self._buf.append(data)

    parser = TableParser(table_id)
    parser.feed(html)
    parser.close()

