import csv
import io


def concat_csv_tables(csv_texts):
    if not csv_texts:
        raise ValueError("csv_texts must not be empty")

    rows = []       # list of (header, data_rows) per document
    headers = None

    for text in csv_texts:
        reader = csv.reader(io.StringIO(text))
        try:
            header = next(reader)
        except StopIteration:
            continue  # empty document, skip
        if headers is None:
            headers = header
        elif header != headers:
            raise ValueError("All documents must share the same columns")
        data = [row for row in reader if row]  # skip blank lines
        rows.append(data)

    if headers is None:
        raise ValueError("No CSV documents with content were provided")
    if not rows:
        return []

    # Determine, per column, whether every value is numeric.
    def try_number(value):
        try:
            return int(value)
        except ValueError:
            try:
                return float(value)
            except ValueError:
                return None

    n_cols = len(headers)
    numeric = [True] * n_cols
    for data in rows:
        for row in data:
            for i in range(n_cols):
                if try_number(row[i]) is None:
                    numeric[i] = False

    # Build the list of dicts.
    result = []
    for data in rows:
        for row in data:
            record = {}
            for i, name in enumerate(headers):
                value = row[i]
                if numeric[i]:
                    value = try_number(value)
                record[name] = value
            result.append(record)
    return result
