from html.parser import HTMLParser


class _FirstTableParser(HTMLParser):
    """Collects the headers and data rows of the first <table> in a document."""

    def __init__(self):
        # convert_charrefs=True makes HTMLParser decode entities (&amp;, &#169;, ...)
        # and deliver them as plain text via handle_data.
        super().__init__(convert_charrefs=True)
        self.found = False        # a <table> was seen somewhere
        self._active = False      # currently inside the first table
        self._depth = 0           # nesting level of tables within the first table
        self.headers = []         # stripped text of every <th>
        self.rows = []             # one list per <tr> that had <td> cells
        self._row = None          # td texts of the current row
        self._cell = None         # text chunks of the current cell
        self._cell_type = None    # 'th' or 'td'

    def _flush_cell(self):
        if self._cell is not None:
            text = ''.join(self._cell).strip()
            if self._cell_type == 'th':
                self.headers.append(text)
            elif self._row is not None:
                self._row.append(text)
            self._cell = None
            self._cell_type = None

    def _flush_row(self):
        self._flush_cell()
        # An empty list means the row had no <td> cells -> skip it.
        if self._row:
            self.rows.append(self._row)
        self._row = None

    def handle_starttag(self, tag, attrs):
        if tag == 'table':
            if not self._active:
                self._active = True
                self._depth = 1
                self.found = True
            else:
                self._depth += 1   # nested table inside a cell
            return
        if not self._active or self._depth > 1:
            return
        if tag == 'tr':
            self._flush_row()      # tolerate unclosed <tr>
            self._row = []
        elif tag in ('td', 'th'):
            self._flush_cell()     # tolerate unclosed <td>/<th>
            self._cell = []
            self._cell_type = tag

    def handle_endtag(self, tag):
        if not self._active:
            return
        if tag == 'table':
            self._depth -= 1
            if self._depth == 0:
                self._flush_row()
                self._active = False
        elif self._depth == 1:
            if tag == 'tr':
                self._flush_row()
            elif tag in ('td', 'th'):
                self._flush_cell()

    def handle_data(self, data):
        if self._active and self._cell is not None:
            self._cell.append(data)

    def close(self):
        super().close()
        self._flush_row()          # flush anything left by malformed markup


def extract_first_table(html):
    """Return (headers, rows) for the first <table> in the given HTML string."""
    parser = _FirstTableParser()
    parser.feed(html)
    parser.close()

    if not parser.found:
        raise ValueError("page contains no table")
    if not parser.rows:
        raise ValueError("table has no data rows")

    return (parser.headers, parser.rows)
```

