        if s and _NUMBER_RE.match(s):
            return float(s.replace(',', ''))
        return None

    rows = [row for row in csv.reader(io.StringIO(csv_text)) if row]
    if not rows:
        return {'means': {}, 'std_devs': {}, 'f_value': None}

    header = rows[0]
    data = rows[1:]

    # Gather parsed values per column (None wherever a cell isn't a number).
    columns = {name: [] for name in header}
    for row in data:
        for i, name in enumerate(header):
            value = parse_number(row[i]) if i < len(row) else None
            columns[name].append(value)

    # Keep only columns where every value parsed as a number.
    numeric = {}
    for name in header:
        values = columns[name]
        if values and all(v is not None for v in values):
            numeric[name] = values

    means = {name: sum(vals) / len(vals) for name, vals in numeric.items()}

    std_devs = {}
    for name, vals in numeric.items():
        m = means[name]
        if len(vals) > 1:
            variance = sum((v - m) ** 2 for v in vals) / (len(vals) - 1)
            std_devs[name] = math.sqrt(variance)
        else:
            std_devs[name] = None  # sample std dev undefined for a single value

    # One-way ANOVA treating each numeric column as a group.
    f_value = None
    if len(numeric) >= 2:
        groups = list(numeric.values())
        all_vals = [v for g in groups for v in g]
        grand_mean = sum(all_vals) / len(all_vals)
        k = len(groups)
        N = len(all_vals)

        ss_between = sum(len(g) * (sum(g) / len(g) - grand_mean) ** 2
                         for g in groups)
        ss_within = sum(sum((v - sum(g) / len(g)) ** 2 for v in g)
                         for g in groups)

        denom_within = ss_within / (N - k)
        denom_between = ss_between / (k - 1)
        if denom_within > 0:
            f_value = denom_between / denom_within
        elif denom_between > 0:
            f_value = float('inf')  # zero within-group variance
        else:
            f_value = None  # all values identical: F undefined (0/0)

    return {'means': means, 'std_devs': std_devs, 'f_value': f_value}
```

**How it works**

1. **Parsing:** The CSV is read with the standard `csv` module, so quoted fields like `"1,000"` come through as single cells. A regex validates the cell as a number *before* stripping commas — this prevents strings like `"1,2"` from being misread as `12`. Exponents, signs, and decimals are supported.

2. **Column selection:** A column is included only if every one of its cells parses as a number; columns containing any non-numeric (or missing) value are dropped entirely.

3. **Statistics:** Means and *sample* standard deviations (dividing by `n − 1`) are computed per column. The F statistic comes from one-way ANOVA across the numeric columns treated as groups:

$$F = \frac{SS_{between}/(k-1)}{SS_{within}/(N-k)}$$

4. **Edge cases:** Fewer than two numeric columns gives `f_value = None`; degenerate variance cases (`0/0` or perfect separation) are handled explicitly rather than raising `ZeroDivisionError`.

**Example**

```python
result = summarize_numeric_csv('A,B\n1,4\n2,5\n3,6\n')
print(result)
# {'means': {'A': 2.0, 'B': 5.0}, 'std_devs': {'A': 1.0, 'B': 1.0}, 'f_value': 13.5}
```

It also handles thousands separators correctly:

```python
summarize_numeric_csv('x,y\n"1,000","2,000"\n"2,000","4,000"\n')
# {'means': {'x': 1500.0, 'y': 3000.0}, 'std_devs': {'x': 707.106..., 'y': 1414.213...},
#  'f_value': 3.0}
```

```python
import json


def _percentile(sorted_vals, q):
    """Percentile via linear interpolation between closest ranks (numpy's default 'linear' method).
    q is a fraction in [0, 1]."""
    n = len(sorted_vals)
    if n == 1:
        return float(sorted_vals[0])
    pos = q * (n - 1)
    lo = int(pos)
    frac = pos - lo
    if lo + 1 < n:
        return sorted_vals[lo] + frac * (sorted_vals[lo + 1] - sorted_vals[lo])
    return float(sorted_vals[lo])


def summarize_values_by_key(json_text):
    """
    Given a JSON string encoding a list of objects mapping keys to numbers,
    return per-key summary statistics: 'mean', 'median', 'q1', 'q3'.
    q1/q3 use linear interpolation between sorted values (numpy-style default).
    Raises ValueError for invalid JSON.
    """
    try:
        data = json.loads(json_text)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON: {e}") from e

    if not isinstance(data, list):
        raise ValueError("JSON must encode a list of objects")

    # Gather values per key; keys missing from some objects are skipped.
    values_by_key = {}
    for obj in data:
        if not isinstance(obj, dict):
            raise ValueError("Each element must be an object")
        for key, value in obj.items():
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError(f"Value for key {key!r} is not a number")
            values_by_key.setdefault(key, []).append(value)

    result = {}
    for key, vals in values_by_key.items():
        s = sorted(vals)
        result[key] = {
            'mean': sum(s) / len(s),
            'median': _percentile(s, 0.5),
            'q1': _percentile(s, 0.25),
            'q3': _percentile(s, 0.75),
        }
    return result
```

**How it works:**

- `json.loads` raises `json.JSONDecodeError`, which is a subclass of `ValueError`; we re-raise it explicitly with a clear message to be safe.
- Values for each key are collected only from the objects that contain that key.
- Quartiles/median use the position formula `pos = q * (n - 1)` and linearly interpolate between the two adjacent sorted values — this is the same default method used by `numpy.percentile` (and `statistics.quantiles(data, method='inclusive')`), and matches the example:
  - Key `'a'`: values `[1, 2, 3, 10]` → median `2.5`, q1 at position `0.75` → `1.75`, q3 at position `2.25` → `4.75`, mean `4.0`.
  - Key `'b'`: values `[4, 6]` → median `5.0`, q1 `4.5`, q3 `5.5`, mean `5.0`.

Example:

```python
>>> summarize_values_by_key('[{"a": 1, "b": 4}, {"a": 2}, {"a": 3, "b": 6}, {"a": 10}]')
{'a': {'mean': 4.0, 'median': 2.5, 'q1': 1.75, 'q3': 4.75},
 'b': {'mean': 5.0, 'median': 5.0, 'q1': 4.5, 'q3': 5.5}}
```
